602	     * Creates a new imp extension for particular bidder having:
603	     * <ul>
604	     * <li>"prebid" field populated with an imp.ext.prebid field value, may be null</li>
605	     * <li>"context" field populated with an imp.ext.context field value, may be null</li>
606	     * <li>"bidder" field populated with an imp.ext.prebid.bidder.{bidder} field value, not null</li>
607	     * </ul>
608	     */
609	    private ObjectNode prepareImpExt(String bidder, ObjectNode impExt, boolean useFirstPartyData) {
610	        final JsonNode impExtPrebid = cleanBidderParamsFromImpExtPrebid(impExt.get(PREBID_EXT));
611	        final JsonNode impExtBidder = bidderParamsFromImpExt(impExt).get(bidder);
612	
613	        final ObjectNode result = mapper.mapper().valueToTree(ExtPrebid.of(impExtPrebid, impExtBidder));
614	
615	        if (impExt.hasNonNull(CONTEXT_EXT)) {
616	            final JsonNode contextNodeCopy = impExt.get(CONTEXT_EXT).deepCopy();
617	            if (!useFirstPartyData && contextNodeCopy.isObject()) {
618	                ((ObjectNode) contextNodeCopy).remove(DATA);
619	            }
620	            result.set(CONTEXT_EXT, contextNodeCopy);
621	        }
622	
623	        return result;
624	    }
